import mods.crtadd.projecte.PlayerAttemptLearnEvent;
import mods.crtadd.projecte.KnowledgeProvider;

events.onPlayerAttemptLearn(function(event as PlayerAttemptLearnEvent){
    var player as IPlayer = event.player; 
